function into_telescope(){
    is_gyro = false;
    gyro_setting_icon.style.display = "none";
    gyro_settings_ele.style.display = "none";
    reset_rotate_origin_button.style.display = "none";
    geometry_hide_panel = new THREE.PlaneGeometry(10, 10);  // 板のサイズ（カメラの前に大きく配置）
    material_hide_panel = new THREE.MeshBasicMaterial({
        color: 0xffffff, // 白色に設定
        opacity: 10,      // 最初は完全に不透明
        transparent: true // 透明にする
    });
    hide_plane = new THREE.Mesh(geometry_hide_panel, material_hide_panel);
    in_transition_telescope = true;
    at_main_content = true;
    panel.visible = false;
    allow_touch_move = false;
    change_constellation_name_button.parentElement.style.display = "none";
    change_location_button.parentElement.style.display = "none";
    change_time_button.parentElement.style.display = "none";
    show_time_and_location_ele.style.display = "none";
    
    canvas.style.cursor = "auto";
    const tl = gsap.timeline();
    // 目標の回転（rad）
    console.log(camera.rotation.y/Math.PI*180);
    camera.rotation.y = camera.rotation.y%(Math.PI*2);
    if(camera.rotation.y>0){
        camera.rotation.y-=Math.PI*2;
    }
    console.log(camera.rotation.y/Math.PI*180);
    const targetRotation = {
        x: -30 * Math.PI / 180,
        y: -Math.PI / 2,
        z: 0
    };
    camera.rotation.order = "YXZ";
    //camera.position.set(0.9,2.3,0)
    // アニメーション実行（2秒でイージング）
    tl.to(camera.rotation, {
        duration: 1,
        x: targetRotation.x,
        y: targetRotation.y,
        z: targetRotation.z,
        ease: "power3.out"
    });
    tl.to(camera.position, {
        x: 0.9,
        y: 2.3,
        z: 0,
        duration: 1,
        ease: "power2.inOut"
    });
    tl.to(camera,{
        zoom:9,
        duration: 1,
        ease: "power2.inOut",
        onUpdate: () => {
            camera.updateProjectionMatrix();
        },
        onComplete:()=>{
            
            hide_plane.position.set(1, 0, 0); // カメラの前に配置（距離を調整）
            hide_plane.rotation.y = -Math.PI/2
            scene.add(hide_plane);
            hide_plane.visible = true;
            hide_plane.material.transparent = true;
            
            star_points.visible = false;
            constellation_lines.forEach(element => {
                element.visible = false;
            });
        }
    });
    tl.to(camera.position,{
        x:0,
        y:1,
        z:0,
        duration:0
    });
    tl.to(camera,{
        zoom:3,
        duration: 0,
        onUpdate: () => {
            telescope.visible = false;
            camera.updateProjectionMatrix();
        }
    })
    const targetRotation2 = {
        x: 45 * Math.PI / 180,
        y: -Math.PI / 2,
        z: 0
    };
    tl.to(camera.rotation, {
        duration: 0,
        x: targetRotation2.x,
        y: targetRotation2.y,
        z: targetRotation2.z,
    });
    tl.to(hide_plane.material.color,{
        duration: 1,
        r: 0,
        g: 0,
        b: 0,
        
        //opacity: 0.3,
        onStart:()=>{
            
            telescope_filter_img.style.display = "block";
            //galaxy_img.style.display = "block";
            
            telescope_filter_img.classList.add("opacity_animation");
            //galaxy_img.classList.add("opacity_animation");
        },
        onComplete: () => {
            telescope_filter_img.classList.add("opacity_animation");
            galaxy_img.classList.add("size_animation");
            select_galaxy_ele.style.display = "block";
            //telescope_filter_img.classList.add("opacity_animation");
            yaw = -Math.PI / 2;   // 左右
            pitch = 45 * Math.PI / 180; // 上下
            scene.remove(hide_plane);
            geometry_hide_panel.dispose()
            material_hide_panel.dispose()
            create_galaxy();
            rotation_pase = 20;
            always_GalaxyRotating = true;
            //scene.remove(hide_plane);
            //in_transition_telescope = false;
        }
    })
}

