        const past_time_ms = now - GalaxyRotateStart_time;
        const progress = (past_time_ms%(GalaxyRotate_duration*rotation_pase))/(GalaxyRotate_duration*rotation_pase);
        addition_angle = total_addition_angle * progress;
        let index = 0;
