            const updated_angleRad = angleRad + addition_angle + current_galaxy_rotate;
            
            army = radius*Math.sin(updated_angleRad);
            armz = radius*Math.cos(updated_angleRad);
            const rotatedX = army * Math.cos(zRotation);
